<?php
namespace App\Services\Media; use App\Contracts\ProtectedMediaStorage; use App\Models\{MediaAsset,MediaVariant,StorageLedgerEntry}; use Illuminate\Support\Str; use RuntimeException;
class MediaVariantProcessor {public function __construct(private ProtectedMediaStorage $storage){}public function process(MediaAsset $asset):void{$source=$asset->variants()->where('variant_type','original')->where('state','ready')->firstOrFail();if(!$this->storage->exists($source->object_key))throw new RuntimeException('Source media is unavailable.');$stream=$this->storage->readStream($source->object_key);$bytes=stream_get_contents($stream);fclose($stream);$image=@imagecreatefromstring($bytes);if(!$image)throw new RuntimeException('Source image is invalid.');foreach([['optimized',2048,88],['thumbnail',640,82]] as [$type,$max,$quality]){$existing=$asset->variants()->where('variant_type',$type)->where('state','ready')->first();if($existing)continue;$w=imagesx($image);$h=imagesy($image);$scale=min(1,$max/max($w,$h));$tw=max(1,(int)round($w*$scale));$th=max(1,(int)round($h*$scale));$target=imagecreatetruecolor($tw,$th);imagecopyresampled($target,$image,0,0,0,0,$tw,$th,$w,$h);ob_start();imagejpeg($target,null,$quality);$out=(string)ob_get_clean();imagedestroy($target);$key=config('media.prefixes.'.($type==='optimized'?'optimized':'thumbnails')).'/groups/'.$asset->group_id.'/'.Str::uuid().'.jpg';$this->storage->put($key,$out,'image/jpeg');MediaVariant::create(['media_asset_id'=>$asset->id,'variant_type'=>$type,'storage_disk'=>$this->storage->disk(),'object_key'=>$key,'mime_type'=>'image/jpeg','size_bytes'=>strlen($out),'checksum_sha256'=>hash('sha256',$out),'width'=>$tw,'height'=>$th,'state'=>'ready']);$ledger=StorageLedgerEntry::firstOrCreate(['idempotency_key'=>'variant-'.$asset->uuid.'-'.$type],['owner_id'=>$asset->owner_id,'group_id'=>$asset->group_id,'media_asset_id'=>$asset->id,'event_type'=>'variant_created','byte_delta'=>strlen($out)]);if($ledger->wasRecentlyCreated)\App\Models\User::whereKey($asset->owner_id)->increment('storage_used',strlen($out));}imagedestroy($image);$asset->update(['state'=>'completed']);}}
